#include <stdio.h>

int main(void) {
    int N;
    double D;

    if (scanf("%d %lf", &N, &D) != 2) {
        return 0;
    }

    double position[1000], charge[1000], dp[1000];

    for (int i = 0; i < N; i++) {
        scanf("%lf %lf", &position[i], &charge[i]);
        dp[i] = 1e100;
    }

    dp[0] = 0.0;

    for (int i = 0; i < N; i++) {
        for (int j = i + 1; j < N; j++) {
            double distance = position[j] - position[i];
            double time = distance * distance / charge[i];
            if (dp[i] + time < dp[j]) {
                dp[j] = dp[i] + time;
            }
        }
    }

    double answer = 1e100;
    for (int i = 0; i < N; i++) {
        double distance = D - position[i];
        double time = distance * distance / charge[i];
        if (dp[i] + time < answer) {
            answer = dp[i] + time;
        }
    }

    printf("%.3f\n", answer);
    return 0;
}
